terraform {
  # Write-only arguments require Terraform 1.11 or later.
  required_version = ">= 1.11.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.7"
    }
  }

  backend "local" {
    path = "terraform.tfstate"
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region for every resource in this module."
  type        = string
  default     = "eu-west-1"
}

variable "project" {
  description = "Name prefix for every resource."
  type        = string
  default     = "demo-tf-secrets-final"
}

variable "secret_version" {
  description = <<-EOT
    Rotation trigger for the write-only argument. Increment to rotate: Terraform
    cannot diff a value it never stored, so the version is what signals intent.
    Keeping it in configuration makes every rotation a reviewed, attributable change.
  EOT
  type        = number
  default     = 1
}

output "secret_arn" {
  description = "Hand this to consumers. The value itself never leaves the vault."
  value       = aws_secretsmanager_secret.app.arn
}

output "state_proof_command" {
  description = "Shows what the state holds: a flag and a version, never the value."
  value       = "terraform state pull | jq '.resources[] | select(.type==\"aws_secretsmanager_secret_version\") | .instances[0].attributes | {secret_string, has_secret_string_wo, secret_string_wo_version}'"
}

